// Rochdale Daily homepage feed request-time guard.
// The static feed is generated by the scraper, but this Function is the final
// publication boundary for /articles/frontpage.json. Editorially removed
// stories are filtered here as defence in depth so a stale deployment/cache or
// race cannot leave a dead/403 story card visible on the paper.

const LIVE_UNTIL = Date.parse('2026-08-09T01:30:00+01:00');
// The takedown workflow writes story_blocklist.json. This Function used to keep
// its own copy of the list, which meant a story removed through one route was
// still served by the other, and nothing kept the two in step. It now reads the
// committed blocklist at request time. The names below remain only as a
// last-resort fallback for the case where that file cannot be read at all.
const FALLBACK_BLOCKED_SLUGS = new Set([
  'crowds-gather-at-rochdale-town-hall-this-afternoon',
  'james-and-georgina-celebrate-their-wedding-at-whitworth-estate',
  'new-stone-circle-installed-near-rochdale',
  'rochdale-borough-council-licensing-sub-committee-meeting-scheduled-for-may-2026',
  'rochdale-valiant-launches-new-media-portal',
  'rochdale-valiant-launches-new-media-portal-for-community-engagement',
  'rochdale-valiant-launches-new-media-portal-for-community-news',
  'rochdale-valiant-launches-new-media-portal-for-local-community',
  'rochdale-valiant-launches-new-media-portal-for-local-news',
  'rochdale-valiant-launches-new-media-portal-to-enhance-community-engagement',
  'rochdale-weather-forecast-sunny-intervals-expected-this-week',
  'rochdale-weather-forecast-warm-and-sunny-days-ahead',
  'sunny-weather-expected-in-rochdale-this-week',
  'traffic-incidents-reported-in-rochdale',
  'traffic-update-for-rochdale-current-conditions-and-alerts',
  'voters-urged-to-support-marlon-west-in-greater-manchester-election',
  'walking-the-rochdale-canal-a-scenic-journey-from-brearley-bridge-to-luddendenfoo'
]);

// Subject-level blocks. A slug list can only stop the exact pages that already
// exist; the scraper regenerates the same story under a new slug every time the
// headline is reworded, which is how six near-identical pages got published.
// The scraper matches story_blocklist.json title_patterns as a lowercase
// substring of the headline -- this Function now does the same, so both ends of
// the pipeline block on the same rule.
const FALLBACK_BLOCKED_TITLE_PATTERNS = ['rochdale valiant'];

function normaliseSlug(value) {
  return String(value == null ? '' : value)
    .replace(/^\.\.\//, '').replace(/\.html$/i, '').trim().toLowerCase();
}

/** Read the committed blocklist. Falls back to the names above if unreadable. */
async function loadBlocklist(env, requestUrl) {
  const slugs = new Set(FALLBACK_BLOCKED_SLUGS);
  const patterns = new Set(FALLBACK_BLOCKED_TITLE_PATTERNS);
  try {
    const url = new URL('/story_blocklist.json', requestUrl);
    const response = await env.ASSETS.fetch(url);
    if (!response.ok) return { slugs, patterns };
    const data = await response.json();
    const listed = Array.isArray(data) ? data : (data && data.slugs);
    if (Array.isArray(listed)) {
      for (const entry of listed) {
        // Keep the fallback names too: a slug removed from the committed file
        // by accident should not quietly come back onto the front page.
        const slug = normaliseSlug(entry && entry.slug ? entry.slug : entry);
        if (slug) slugs.add(slug);
      }
    }
    const titles = data && !Array.isArray(data) ? data.title_patterns : null;
    if (Array.isArray(titles)) {
      for (const entry of titles) {
        const pattern = String(entry == null ? '' : entry).trim().toLowerCase();
        if (pattern) patterns.add(pattern);
      }
    }
  } catch (_) { /* fall through to the fallback sets */ }
  return { slugs, patterns };
}

function isBlocked(article, blocklist) {
  if (blocklist.slugs.has(slugOf(article))) return true;
  const title = String(article?.title || '').trim().toLowerCase();
  if (!title) return false;
  for (const pattern of blocklist.patterns) {
    if (title.includes(pattern)) return true;
  }
  return false;
}

// --------------------------------------------------------------------------
// Breaking news from the GMP watcher.
//
// scraper/gmp_watch.py writes breaking.json within a minute of GMP posting.
// Reading it here, at request time, is what makes that minute count: the story
// reaches the front page as soon as Pages has the commit, with no site rebuild
// and without queueing behind a scrape that holds rd-site-writer for up to 45
// minutes. This is the same trick the live-festival story below already uses --
// a story served from the edge that is not in the static feed at all.
//
// Only entries the watcher marked 'live' appear. Anything it held for legal
// review stays in the file and stays off the site.
// --------------------------------------------------------------------------

const BREAKING_KICKER = 'BREAKING';

function breakingToArticle(entry, nowIso) {
  const slug = normaliseSlug(entry.slug);
  const quote = String(entry.quote || '').trim();
  const attribution = String(entry.attribution || 'Greater Manchester Police said:');
  const sourceUrl = String(entry.source_url || '');
  const paragraphs = quote
    .split(/\n{2,}/)
    .map(p => p.trim())
    .filter(Boolean)
    .map(p => `<p>${escapeHtml(p)}</p>`)
    .join('');
  return {
    id: `breaking:${slug}`,
    // articles/${slug}.html is how the homepage builds every card link, so
    // escaping one level up puts the reader on the Function-rendered page.
    slug: `../breaking/${slug}`,
    story_key: `breaking:${slug}`,
    title: String(entry.title || ''),
    excerpt: quote.slice(0, 220),
    content_html: `<p><strong>${escapeHtml(attribution)}</strong></p>${paragraphs}`,
    area: String(entry.area || 'rochdale'),
    category: String(entry.category || 'crime'),
    types: ['news'],
    source_kind: 'official-statement',
    status: 'published',
    published_at: entry.published_at,
    first_published_at: entry.published_at,
    last_updated_at: entry.published_at,
    scraped_at: entry.detected_at || entry.published_at,
    source_name: String(entry.source_name || 'Greater Manchester Police'),
    source_url: sourceUrl,
    source_names: [String(entry.source_name || 'Greater Manchester Police')],
    source_urls: sourceUrl ? [sourceUrl] : [],
    image_url: String(entry.image_url || 'assets/img/cards/police.jpg'),
    image_credit: 'Rochdale Daily',
    byline: String(entry.byline || 'Rochdale Daily'),
    kicker: BREAKING_KICKER,
    is_ongoing: true,
    ongoing_label: BREAKING_KICKER,
    breaking: true,
    police_matter: true,
    developing: true,
    rewrite_quality_checked: true,
    publication_route: 'gmp-breaking-watch'
  };
}

function escapeHtml(value) {
  return String(value == null ? '' : value)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

async function loadBreaking(env, requestUrl, now) {
  try {
    const url = new URL('/breaking.json', requestUrl);
    const response = await env.ASSETS.fetch(url);
    if (!response.ok) return [];
    const data = await response.json();
    const items = Array.isArray(data) ? data : (data && data.items);
    if (!Array.isArray(items)) return [];
    return items
      .filter(entry => entry && entry.status === 'live' && entry.title && entry.slug)
      .filter(entry => {
        const expires = Date.parse(entry.expires_at || '');
        return !Number.isFinite(expires) || expires > now.getTime();
      })
      .sort((a, b) => Date.parse(b.published_at || 0) - Date.parse(a.published_at || 0));
  } catch (_) {
    return [];
  }
}

// Paid-for advertisement features are published as articles, and this feed is
// ordered newest-first, so a freshly published one would otherwise sit among
// the top stories. The homepage draws its lead, top stories and latest panel
// from the first nine entries: sponsored pieces are held below that line. They
// stay in the feed, in order, from position ten onwards.
const SPONSORED_FLOOR = 9;

// Reserve features (evergreen folklore and explainers) are never top stories
// either: same test as scraper/feature_policy.py is_reserve_feature.
function isReserveFeature(article) {
  return article.is_evergreen === true
    || Boolean(article.evergreen_id)
    || String(article.publication_route || '').toLowerCase() === 'evergreen_fallback'
    || String(article.source_kind || '').toLowerCase() === 'evergreen';
}

// Daily briefings (Morning Briefing / Evening Wrap-Up) summarise stories that
// are already on the page: 2.6 views each against 11.7 for a crime story
// (9-27 Oct 2026). Same test as scraper/feature_policy.py is_daily_briefing.
function isDailyBriefing(article) {
  return Boolean(article.briefing_slot)
    || String(article.publication_route || '').toLowerCase() === 'daily-briefing';
}

// Traffic notices (roadworks, road closures) are held below the top nine too
// (editor's rule, 9 Nov 2026): two 03:21 roadworks notices led the paper over
// seven Remembrance Sunday stories. Same test as scraper/feature_policy.py
// is_traffic_notice.
const TRAFFIC_HEADLINE = /\b(?:road\s*works?|road closures?|(?:street|lane|road|avenue|drive)s? (?:in \w+ )?(?:to|will) close\b|traffic diversions?|temporary traffic lights|lane closures?|resurfacing)\b/i;
// Warnings readers need now always sit at position 2, under crime (editor's
// rule, 9 Nov 2026), and are never treated as traffic notices. Same test as
// scraper/feature_policy.py is_public_warning.
const PUBLIC_WARNING = /\b(?:(?:yellow|amber|red) (?:weather )?warnings?|weather warnings?|met office warnings?|(?:snow|ice|wind|rain|fog|thunderstorm|heat|flood) warnings?|flood alerts?|power cuts?|blackouts?|power outages?|without power|bomb scares?|suspicious (?:package|item|device|object)s?|controlled explosion|bomb disposal|evacuat\w*|lock ?downs?|locked down|gas leaks?)\b/i;
const NAMED_STORM = /\bStorm [A-Z][a-z]+\b/;
const COLLISION_CLOSURE = /\b(?:crash|collision|accident|lorry fire|overturned)\b.*\b(?:clos\w*|shut|blocked)\b|\b(?:closed|shut|blocked)\b.*\b(?:crash|collision|accident)\b/i;
function isPublicWarning(article) {
  const title = String(article.title || '');
  return PUBLIC_WARNING.test(title) || NAMED_STORM.test(title) || COLLISION_CLOSURE.test(title);
}

function isTrafficNotice(article) {
  if (isPublicWarning(article)) return false;
  const category = String(article.category || '').trim().toLowerCase();
  const types = Array.isArray(article.types) ? article.types.map((t) => String(t).trim().toLowerCase()) : [];
  return category === 'traffic' || types.includes('traffic') || TRAFFIC_HEADLINE.test(String(article.title || ''));
}

function demoteSponsored(list, floor) {
  const top = [];
  const held = [];
  const rest = [];
  for (const article of list) {
    if (top.length < floor) {
      (article && (article.sponsored === true || isReserveFeature(article) || isDailyBriefing(article) || isTrafficNotice(article)) ? held : top).push(article);
    } else {
      rest.push(article);
    }
  }
  return [...top, ...held, ...rest];
}

// Today's most-read (editor's rule, 9 Nov 2026): positions 1 and 2 keep the
// crime and warning rules; from position 3 down, stories opened at least
// MOST_READ_MIN_VIEWS times today (Europe/London day) rise in order of views.
// Counts come from /api/story-views (D1 binding STORY_VIEWS_DB). Sponsored,
// traffic, reserve-feature and briefing pieces never rise into the top nine,
// and editor pins hold their position.
const MOST_READ_FIXED = 2;
const MOST_READ_MIN_VIEWS = 3;
const MOST_READ_CACHE_MS = 60 * 1000;
let mostReadCache = { day: '', at: 0, views: null };

function londonDay(date = new Date()) {
  return new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/London', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
}

/** Returns a Map slug -> views for today, or null when counts cannot be read. */
async function loadTodaysViews(env, now) {
  const db = env.STORY_VIEWS_DB;
  if (!db) return null;
  const day = londonDay(now);
  const nowMs = now.getTime();
  if (mostReadCache.views && mostReadCache.day === day && nowMs - mostReadCache.at < MOST_READ_CACHE_MS) {
    return mostReadCache.views;
  }
  try {
    const result = await db.prepare(
      'SELECT slug, views FROM story_views WHERE day = ?1 AND views >= ?2'
    ).bind(day, MOST_READ_MIN_VIEWS).all();
    const views = new Map((result.results || []).map((row) => [normaliseSlug(row.slug), Number(row.views) || 0]));
    mostReadCache = { day, at: nowMs, views };
    return views;
  } catch (error) {
    // "no such table" before the first view of all time is an empty day, not
    // a failure.
    if (/no such table/i.test(String(error && error.message))) {
      const views = new Map();
      mostReadCache = { day, at: nowMs, views };
      return views;
    }
    return null;
  }
}

function canRiseOnViews(article, isPinned) {
  return Boolean(article)
    && article.sponsored !== true
    && !isPinned(article)
    && !isReserveFeature(article)
    && !isDailyBriefing(article)
    && !isTrafficNotice(article);
}

/**
 * Positions [0, fixed) are untouched. Below them, stories with views today
 * move up in views order (ties: newer first) into the slots the eligible
 * stories already occupy, so nothing held below the top nine is pulled up
 * past ineligible pieces' positions and pins stay exactly where they were.
 */
function applyMostRead(list, views, { fixed = MOST_READ_FIXED, isPinned = () => false } = {}) {
  if (!views || !views.size || list.length <= fixed) return { list, promoted: 0 };
  const head = list.slice(0, fixed);
  const tail = list.slice(fixed);
  const slotIdx = [];
  const movable = [];
  tail.forEach((article, index) => {
    if (canRiseOnViews(article, isPinned)) { slotIdx.push(index); movable.push(article); }
  });
  const viewsOf = (article) => views.get(slugOf(article)) || 0;
  const ranked = movable
    .map((article, order) => ({ article, order, v: viewsOf(article) }))
    .sort((a, b) => (b.v - a.v) || (a.v && b.v ? storyTime(b.article) - storyTime(a.article) : a.order - b.order));
  const promoted = ranked.filter((entry) => entry.v > 0).length;
  const next = tail.slice();
  slotIdx.forEach((slot, i) => { next[slot] = ranked[i].article; });
  next.forEach((article) => {
    const v = viewsOf(article);
    if (v > 0) article.views_today = v;
  });
  return { list: [...head, ...next], promoted };
}

function storyTime(article) {
  const value = article?.first_published_at || article?.published_at || article?.last_updated_at || '';
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function slugOf(article) {
  return normaliseSlug(article?.slug);
}

function liveStory(nowIso) {
  return {
    id: 'feel-good-festival-2026-live',
    slug: '../feel-good-live',
    story_key: 'editorial:feel-good-festival-2026-live',
    title: 'LIVE: Rochdale Feel Good Festival 2026 — updates throughout the day',
    excerpt: 'Follow Rochdale Daily live from Feel Good Festival 2026, with Gabrielle, Ash, Starsailor, town-centre updates, timings, food and drink, travel and everything happening across Rochdale.',
    content_html: '<p>Follow Rochdale Daily’s rolling live coverage of Feel Good Festival 2026 throughout Saturday 8 August.</p>',
    area: 'rochdale', category: 'news', types: ['news'], source_kind: 'editorial', status: 'published',
    published_at: '2026-08-08T07:00:00Z', first_published_at: '2026-08-08T07:00:00Z', last_updated_at: nowIso, scraped_at: nowIso,
    source_name: 'Rochdale Daily', source_url: 'https://rochdaledaily.co.uk/feel-good-live.html', source_names: ['Rochdale Daily'], source_urls: ['https://rochdaledaily.co.uk/feel-good-live.html'],
    image_url: 'assets/img/cards/rochdale-town-hall.jpg', image_credit: 'Rochdale Daily', byline: 'Rochdale Daily', manual_article: true,
    editorial_lock: true, publication_route: 'editorial-live', rewrite_quality_checked: true, featured: true, force_lead: true,
    is_ongoing: true, ongoing_label: 'LIVE', update_count: 5, frontpage_rank: 0, frontpage_priority: 10000, slot: 'lead'
  };
}

export async function onRequest(context) {
  const { request, env } = context;
  const assetUrl = new URL(request.url);
  const upstream = await env.ASSETS.fetch(assetUrl);
  if (!upstream.ok) return upstream;

  let data;
  try { data = await upstream.json(); } catch (_) { return upstream; }
  if (!data || !Array.isArray(data.articles)) {
    return new Response(JSON.stringify(data), { status: 200, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' } });
  }

  const now = new Date();
  const nowIso = now.toISOString();
  const blocklist = await loadBlocklist(env, request.url);
  let articles = data.articles.filter(a => a && a.id !== 'feel-good-festival-2026-live' && !isBlocked(a, blocklist));
  // Editor pins (featured: true + frontpage_until in the future) go first, then
  // everything else newest-first. Until 9 Nov 2026 this sort was purely by
  // time, so a pin set in manual_articles never held the top of the live page:
  // the Remembrance Sunday roundup, pinned for 8 Nov, sat below the day's later
  // small stories. Among several pins, the one pinned longest (latest
  // frontpage_until) leads, then the newest.
  const nowMs = now.getTime();
  const pinUntil = (article) => {
    if (!article || article.featured !== true) return 0;
    const until = Date.parse(article.frontpage_until || '');
    return Number.isFinite(until) && until >= nowMs ? until : 0;
  };
  articles.sort((a, b) => {
    const pa = pinUntil(a);
    const pb = pinUntil(b);
    if (Boolean(pa) !== Boolean(pb)) return pa ? -1 : 1;
    if (pa !== pb) return pb - pa;
    return storyTime(b) - storyTime(a);
  });
  articles = demoteSponsored(articles, SPONSORED_FLOOR);
  // Crime always leads (editor's rule, 9 Nov 2026): the newest crime story in
  // the feed takes position 1, ahead of editor pins. Crime is among the most-
  // read categories. With no crime story in the feed the order is unchanged.
  const crimeIndex = articles.findIndex((article) => article
    && String(article.category || '').trim().toLowerCase() === 'crime'
    && article.sponsored !== true);
  if (crimeIndex > 0) articles.unshift(articles.splice(crimeIndex, 1)[0]);
  // Warnings always take position 2 (editor's rule, 9 Nov 2026): the newest
  // weather warning, power cut, road-closing collision, bomb scare, evacuation,
  // school lockdown or gas leak in the feed, under the crime lead.
  const warningIndex = articles.findIndex((article, index) => index > 0 && article
    && article.sponsored !== true && isPublicWarning(article));
  if (warningIndex > 1) articles.splice(1, 0, articles.splice(warningIndex, 1)[0]);

  // Today's most-read fill from position 3 down (editor's rule, 9 Nov 2026).
  // When the counts cannot be read the order above stands and the response
  // says so in x-rd-most-read, rather than guessing.
  const todaysViews = await loadTodaysViews(env, now);
  let mostReadStatus = 'unavailable';
  if (todaysViews) {
    const applied = applyMostRead(articles, todaysViews, { isPinned: (a) => Boolean(pinUntil(a)) });
    articles = applied.list;
    mostReadStatus = `promoted=${applied.promoted}`;
  }

  // Breaking entries go above the sorted feed but below a running live blog.
  // The blocklist applies to them too: a story you have taken down must not
  // come back through the breaking door.
  const breakingEntries = await loadBreaking(env, request.url, now);

  // Once the pipeline has published its own article from the same GMP post,
  // the canonical version wins and the breaking card steps aside -- otherwise
  // the front page carries the story twice, the stub above the real thing.
  const publishedSourceUrls = new Set();
  for (const article of articles) {
    for (const url of [article.source_url, ...(Array.isArray(article.source_urls) ? article.source_urls : [])]) {
      if (url) publishedSourceUrls.add(String(url).trim());
    }
  }
  const breakingArticles = breakingEntries
    .filter(entry => !publishedSourceUrls.has(String(entry.source_url || '').trim()))
    .map(entry => breakingToArticle(entry, nowIso))
    .filter(article => !isBlocked(article, blocklist));
  if (breakingArticles.length) articles.unshift(...breakingArticles);

  if (now.getTime() <= LIVE_UNTIL) articles.unshift(liveStory(nowIso));

  articles.forEach((article, index) => {
    article.frontpage_rank = index;
    article.frontpage_priority = index === 0 ? 10000 : Math.max(1, 1000 - index);
    article.slot = index === 0 ? 'lead' : index === 1 ? 'secondary-1' : index === 2 ? 'secondary-2' : '';
  });

  data.articles = articles;
  data.count = articles.length;
  data.generated_at = nowIso;
  if (articles[0]?.id === 'feel-good-festival-2026-live') {
    const liveTitle = articles[0].title;
    const existing = String(data.breaking || '').trim();
    data.breaking = liveTitle + (existing && !existing.includes(liveTitle) ? '     •     BREAKING     •     ' + existing : '');
  }

  // Put breaking headlines in the ticker too. A card the reader has to scroll
  // to is not really breaking.
  if (breakingArticles.length) {
    const headlines = breakingArticles.map(a => a.title).filter(Boolean);
    const existing = String(data.breaking || '').trim();
    const fresh = headlines.filter(title => !existing.includes(title));
    if (fresh.length) {
      data.breaking = [...fresh, existing].filter(Boolean).join('     •     BREAKING     •     ');
    }
  }
  data.breaking_count = breakingArticles.length;
  data.most_read = mostReadStatus;

  return new Response(JSON.stringify(data), {
    status: 200,
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': 'no-store, no-cache, must-revalidate, max-age=0',
      'x-rd-homepage-fix': 'editorial-blocklist-v2',
      'x-rd-most-read': mostReadStatus
    }
  });
}
